--------------------------------------------------------------------------------
-- Start of every database job, run as ADMIN: gives the pipeline user a new random password for this job only
-- (generated by db/run.sh, masked in the logs, never stored). Nothing happens when the user does not exist yet -
-- bootstrap (3.2) then creates it with this password. Substitution variables: ci_user, ci_pw.
--------------------------------------------------------------------------------
set define on verify off feedback off serveroutput on
declare
    l_user constant varchar2(128) := dbms_assert.simple_sql_name(upper('&ci_user'));
    l_n    pls_integer;
begin
    select count(*) into l_n from dba_users where username = l_user;
    if l_n = 0 then
        dbms_output.put_line('user ' || l_user || ' does not exist yet - bootstrap creates it');
        return;
    end if;
    execute immediate 'alter user ' || l_user || ' identified by "' || q'[&ci_pw]' || '" account unlock';
    dbms_output.put_line('user ' || l_user || ': new password for this job');
end;
/
